//For the #WCCChallenge, theme: "spooky"
var xdim, ydim;
var target;
var fade = false;

function setup() {
	createCanvas(windowWidth, windowHeight);
	ydim = height / 3;
	xdim = ydim / 1.5;
	background(0);
	target = createVector(0, 0);
	drawSkulls();
}

function drawSkulls() {
	blendModebackground(color(random(40), random(40), random(40)));
	let count = 1;
	for (let y = ydim / 2.2; y < height; y += (Math.max(0.001, Math.abs(ydim)) || 1)) {
		for (let x = xdim / 2 - (count % 2) * xdim / 2; x < width + xdim; x += (Math.max(0.001, Math.abs(xdim)) || 1)) {
			drawSkull(x, y + random(-ydim / 24, ydim / 24), ydim / 4);
		}
		count++;
	}
}

function drawSkull(sx, sy, sz) {

	//Cranium and jaw
	//let bone = color(random(80), random(40), random(80));
	//if(floor(random(5))==0) 
	let bone = color(random(235, 245), random(235, 245), random(235, 245)); //whitish skulls
	drawCranium(sx, sy, sz, bone);
	drawJaw(sx, sy, sz, bone);

	//Skull adornments
	let crown = color(random(200), random(200), random(200));
	halfFlower(sx, sy - 1.6 * sz, sz / 4, crown, 2 * floor(random(4, 7)), 0, 0, false);
	let chin = color(random(200), random(100), random(200));
	let chinType = floor(random(2));
	if (chinType == 0) {
		halfFlower(sx, sy + 2 * sz, sz / 5, chin, 2 * floor(random(4, 7)), 100, PI, true);
	} else if (chinType == 1) {
		halfFlower(sx + sz / 4, sy + 1.8 * sz, sz / 7, chin, 2 * floor(random(4, 7)), 100, 7 * QUARTER_PI, true);
		halfFlower(sx - sz / 4, sy + 1.8 * sz, sz / 7, chin, 2 * floor(random(4, 7)), 100, QUARTER_PI, true);
	}
	let temples = color(random(200), random(100), random(200));
	halfFlower(sx + 1.2 * sz, sy - sz, sz / 6, temples, 2 * floor(random(4, 7)), 100, PI / 2.8, false);
	halfFlower(sx - 1.2 * sz, sy - sz, sz / 6, temples, 2 * floor(random(4, 7)), 100, -PI / 2.8, false);

	//Teardrops on face
	let drop = color(random(200), random(100), random(200));
	let ang = random(-PI / 8, PI / 4);
	let type = 'drop';
	tearDrop(sx + sz / 1.5, sy + sz / 1.75, sz / 3, -1, drop, ang * 1.2, PI / 1.25, type);
	tearDrop(sx - sz / 1.5, sy + sz / 1.75, sz / 3, 1, drop, -ang * 1.2, PI / 1.25, type);
	if (floor(random(5)) == 0) type = 'square';
	tearDrop(sx + sz / 1.8, sy - sz / 1.25, sz / 3, -1, drop, ang / 2, PI / 1.1, type);
	tearDrop(sx - sz / 1.8, sy - sz / 1.25, sz / 3, 1, drop, -ang / 2, PI / 1.1, type);
	if (floor(random(3)) == 0) type = 'square';
	tearDrop(sx + sz / 1.5, sy - 1.5 * sz, sz / 3, -1, drop, ang, PI / 2, type);
	tearDrop(sx - sz / 1.5, sy - 1.5 * sz, sz / 3, 1, drop, -ang, PI / 2, type);

	//Eyes
	let col = color(random(120, 255), random(100, 185), random(255));
	var num = 3 * floor(random(3, 7));
	let esz = random(0.15 * sz, 0.2 * sz);
	drawEye(sx - 0.55 * sz, sy + sz / 8, esz, col, num, -PI / 18);
	drawEye(sx + 0.55 * sz, sy + sz / 8, esz, col, num, PI / 18);

	//Grin
	let smile = random(0.2, 0.45);
	let lips = color(random(120), random(50), random(50));
	if (floor(random(3)) > 0) drawHeart(sx, sy + sz + smile * sz, sz * 0.8, sz / 2.5, 14, 8, random(0, 40), 5, false, -1, lips);
	let teeth = random(120, 240);
	for (let a = -QUARTER_PI + QUARTER_PI / 12; a < 0; a += (Math.max(0.001, Math.abs(QUARTER_PI / 6)) || 1)) {
		var x = 0.9 * sz * sin(a);
		var y = sz + smile * sz * cos(a);
		let s = 0.06 * sz * cos(a);
		if (a > -QUARTER_PI / 6) s *= 1.25;
		drawTooth(sx + x, sy + y, s * 1.5, teeth, -1.8);
		drawTooth(sx - x, sy + y, s * 1.5, teeth, -1.8);

	}
	for (let a = -QUARTER_PI + QUARTER_PI / 12; a < 0; a += (Math.max(0.001, Math.abs(QUARTER_PI / 6)) || 1)) {
		var x = 0.9 * sz * sin(a);
		var y = 1.15 * sz + smile * sz * cos(a);
		var s = 0.06 * sz * cos(a);
		drawTooth(sx + x, sy + y, s * 1.5, teeth, 1.1);
		drawTooth(sx - x, sy + y, s * 1.5, teeth, 1.1);
	}

	//Nose
	let h = random(0.4 * sz, 0.5 * sz);
	let a = floor(random(10, 50));
	let b = floor(random(2, 6));
	drawHeart(sx, sy + 0.6 * sz, 0.3 * h, 0.6 * h, a, b, col, h / 3, true, 1, 'black');

	//Forehead design
	let forehead = color(random(50, 200), 0, 0);
	let choice = floor(random(3));
	if (choice == 0) drawCross(sx, sy - sz / 1.75, sz / 1.2, forehead);
	else if (choice == 1) drawHeart(sx, sy - sz / 1.8, sz / 4, sz / 4, floor(random(2, 5)), floor(random(2, 5)), forehead, 5, false, -1, 'black');
	else drawEye(sx, sy - sz / 1.8, sz / 10, forehead, 12, 0);

}

function mousePressed() {
	if (!fade) {
		fade = true;
	} else {
		setTimeout(drawSkulls, 1000);
		fade = false;
	}
}

function draw() {
	if (fade) {
		background(0, 5);
		target.lerp(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))), 0.1);
		translate(target.x, target.y);
		rotate(sin(frameCount / 30) / 10);
		drawSkull(0, 0, height / 5);
	}
}
